amqp_connection_state_t conn = amqp_new_connection();
amqp_socket_t *sock = amqp_tcp_socket_new(conn);
amqp_socket_open(sock, host, 5672);
amqp_login(conn, "/", 0, 131072, 0, AMQP_SASL_METHOD_PLAIN, user, pass);
amqp_channel_open(conn, 1);
amqp_basic_consume(conn, 1, qname, amqp_empty_bytes, 0, 1, 0, amqp_empty_table);
amqp_envelope_t env;
while (amqp_consume_message(conn, &env, NULL, 0).reply_type == AMQP_RESPONSE_NORMAL) {
  handle_order(env.message.body.bytes, env.message.body.len);
  amqp_destroy_envelope(&env);
}
